//! Argument parity against v4 (design §14 "Argument parity").
//!
//! The fixtures under `tests/fixtures/` are generated by `gen_args.py` from the Python parser in
//! this repository (see that script for how to regenerate them). Every test collects all
//! mismatches before failing so one run shows the full picture.

use std::collections::BTreeSet;
use std::path::PathBuf;

use chrono::{DateTime, NaiveDateTime};
use regex::Regex;
use serde_json::Value;

use meerschaum_cli::actions::{self, CORE_ACTIONS};
use meerschaum_cli::dispatch::{self, Runtime, SuccessTuple};
use meerschaum_cli::parse::{parse_arguments, parse_line};
use meerschaum_cli::sysargs;
use meerschaum_cli::types::{self, DateContext};
use meerschaum_cli::value::{PyException, PyValue, args_to_fixture_json};
use meerschaum_cli::{help, schema, spec};

fn fixtures_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
}

fn load(name: &str) -> Value {
    let text = std::fs::read_to_string(fixtures_dir().join(name)).expect("fixture exists");
    serde_json::from_str(&text).expect("valid JSON fixture")
}

fn strings(v: &Value) -> Vec<String> {
    v.as_array()
        .expect("array")
        .iter()
        .map(|s| s.as_str().expect("string").to_string())
        .collect()
}

fn ctx(fixture: &Value) -> DateContext {
    let now = DateTime::parse_from_rfc3339(fixture["now"].as_str().unwrap())
        .unwrap()
        .naive_utc();
    let default = NaiveDateTime::parse_from_str(
        fixture["dateutil_default"].as_str().unwrap(),
        "%Y-%m-%dT%H:%M:%S",
    )
    .unwrap();
    DateContext {
        now_utc: now,
        dateutil_default: default,
        local_year: fixture["local_year"].as_i64().unwrap() as i32,
    }
}

fn exc_json(e: &PyException) -> Value {
    PyValue::Exception(e.clone()).to_fixture_json()
}

/// Compare two JSON objects key by key, returning human-readable differences.
fn diff_maps(expected: &Value, actual: &Value) -> Vec<String> {
    let (Some(e), Some(a)) = (expected.as_object(), actual.as_object()) else {
        return if expected == actual {
            vec![]
        } else {
            vec![format!("expected {expected}, got {actual}")]
        };
    };
    let mut diffs = Vec::new();
    let keys: BTreeSet<&String> = e.keys().chain(a.keys()).collect();
    for k in keys {
        match (e.get(k), a.get(k)) {
            (Some(x), Some(y)) if x == y => {}
            (Some(x), Some(y)) => diffs.push(format!("  {k}: python={x} rust={y}")),
            (Some(x), None) => diffs.push(format!("  {k}: python={x} rust=<missing>")),
            (None, Some(y)) => diffs.push(format!("  {k}: python=<missing> rust={y}")),
            (None, None) => {}
        }
    }
    diffs
}

/// `argparse`'s "ambiguous option: ... could match ..." lists every option string, so the
/// arguments added since v4 ([`spec::V5_ONLY_DESTS`]) are taken out of the Rust message before it
/// is compared with the v4 recording.
fn without_v5_options(mut args: Value) -> Value {
    let added: Vec<String> = spec::V5_ONLY_DESTS
        .iter()
        .filter_map(|dest| spec::by_dest(dest))
        .flat_map(|a| a.option_strings.iter().map(|s| format!(", {s}")))
        .collect();
    if let Some(message) = args
        .get_mut("_argparse_exception")
        .and_then(|e| e.get_mut("message"))
        && let Some(text) = message.as_str()
        && text.starts_with("ambiguous option:")
    {
        let mut text = text.to_string();
        for option in &added {
            text = text.replace(option.as_str(), "");
        }
        *message = Value::String(text);
    }
    args
}

fn report(name: &str, failures: &[String], total: usize) {
    if !failures.is_empty() {
        let shown: Vec<&String> = failures.iter().take(40).collect();
        panic!(
            "{name}: {} of {total} cases differ from Python:\n{}",
            failures.len(),
            shown
                .iter()
                .map(|s| s.as_str())
                .collect::<Vec<_>>()
                .join("\n")
        );
    }
    eprintln!("{name}: {total} cases match Python");
}

#[test]
fn parse_arguments_matches_python() {
    let fixture = load("args.json");
    let ctx = ctx(&fixture);
    let cases = fixture["cases"].as_array().unwrap();
    let mut failures = Vec::new();
    for case in cases {
        let sysargs = strings(&case["sysargs"]);
        let rust = parse_arguments(&sysargs, &ctx);
        match (case.get("raises"), rust) {
            (Some(expected), Err(e)) => {
                if *expected != exc_json(&e) {
                    failures.push(format!(
                        "{sysargs:?}: raises python={expected} rust={}",
                        exc_json(&e)
                    ));
                }
            }
            (Some(expected), Ok(args)) => {
                failures.push(format!(
                    "{sysargs:?}: python raised {expected}, rust returned {}",
                    args_to_fixture_json(&args)
                ));
            }
            (None, Err(e)) => failures.push(format!("{sysargs:?}: rust raised {}", exc_json(&e))),
            (None, Ok(args)) => {
                let diffs = diff_maps(
                    &case["args"],
                    &without_v5_options(args_to_fixture_json(&args)),
                );
                if !diffs.is_empty() {
                    failures.push(format!("{sysargs:?}:\n{}", diffs.join("\n")));
                }
                // The arguments-dict → sysargs round trip.
                let expected = &case["dict_to_sysargs"];
                match sysargs::parse_dict_to_sysargs(&args) {
                    Ok(back) => {
                        if expected.get("ok") != Some(&Value::from(back.clone())) {
                            failures.push(format!(
                                "{sysargs:?}: dict_to_sysargs python={expected} rust={back:?}"
                            ));
                        }
                    }
                    Err(e) => {
                        if expected.get("raises") != Some(&exc_json(&e)) {
                            failures.push(format!(
                                "{sysargs:?}: dict_to_sysargs python={expected} rust raised {}",
                                exc_json(&e)
                            ));
                        }
                    }
                }
            }
        }
    }
    report("parse_arguments", &failures, cases.len());
}

/// v4's serialized chain (`["start", "pipeline", ...]`) in its rc15 form (`["chain", ...]`).
fn v4_chain_to_current(value: &Value) -> Value {
    match value.as_array() {
        Some(items) if items.len() >= 2 && items[0] == "start" && items[1] == "pipeline" => {
            let mut out = vec![Value::from("chain")];
            out.extend(items[2..].iter().cloned());
            Value::Array(out)
        }
        _ => value.clone(),
    }
}

/// A v4 entry step of a serialized chain, with its action words in the rc15 form.
fn v4_chain_step_to_current(step: &Value) -> Value {
    let mut step = step.clone();
    if let Some(map) = step.as_object_mut() {
        for key in ["action", "sysargs", "filtered_sysargs"] {
            if let Some(value) = map.get(key) {
                let current = v4_chain_to_current(value);
                map.insert(key.to_string(), current);
            }
        }
    }
    step
}

#[test]
fn chains_and_pipelines_match_python() {
    let fixture = load("args.json");
    let ctx = ctx(&fixture);
    let chains = fixture["chains"].as_array().unwrap();
    let mut failures = Vec::new();
    let capture_json = |r: Result<Value, PyException>| match r {
        Ok(v) => serde_json::json!({ "ok": v }),
        Err(e) => serde_json::json!({ "raises": exc_json(&e) }),
    };
    for chain in chains {
        let sysargs = strings(&chain["sysargs"]);
        let (before, after) = sysargs::split_pipeline_sysargs(&sysargs);
        let split_pipeline = Value::from(vec![
            Value::from(before.clone()),
            Value::from(after.clone()),
        ]);
        if chain["split_pipeline"] != split_pipeline {
            failures.push(format!(
                "{sysargs:?}: split_pipeline python={} rust={split_pipeline}",
                chain["split_pipeline"]
            ));
        }
        let chained = capture_json(sysargs::split_chained_sysargs(&sysargs).map(Value::from));
        if chain["split_chained"] != chained {
            failures.push(format!(
                "{sysargs:?}: split_chained python={} rust={chained}",
                chain["split_chained"]
            ));
        }
        let has_api = capture_json(Ok(Value::from(sysargs::sysargs_has_api_executor_keys(
            &sysargs,
        ))));
        if chain["has_api_executor_keys"] != has_api {
            failures.push(format!("{sysargs:?}: has_api_executor_keys"));
        }
        let removed = capture_json(Ok(Value::from(sysargs::remove_api_executor_keys(&sysargs))));
        if chain["remove_api_executor_keys"] != removed {
            failures.push(format!(
                "{sysargs:?}: remove_api_executor_keys python={} rust={removed}",
                chain["remove_api_executor_keys"]
            ));
        }
        // rc15 (Q31): chains serialize under the hidden `chain` action instead of v4's
        // `start pipeline` (which now starts saved Pipelines); the payload is v4's, and v4's
        // form still compresses (and runs) the same.
        let pipeline = sysargs::get_pipeline_sysargs(&before, &after, None);
        let expected_pipeline = v4_chain_to_current(&chain["pipeline_sysargs"]);
        if expected_pipeline != Value::from(pipeline.clone()) {
            failures.push(format!(
                "{sysargs:?}: pipeline_sysargs python={expected_pipeline} rust={pipeline:?}",
            ));
        }
        let compressed =
            capture_json(sysargs::compress_pipeline_sysargs(&pipeline).map(Value::from));
        // A chain with nothing to compress comes back as it is: in its own (current) form.
        let expected_compressed = if chain["compressed"]["ok"] == chain["pipeline_sysargs"] {
            serde_json::json!({ "ok": v4_chain_to_current(&chain["pipeline_sysargs"]) })
        } else {
            chain["compressed"].clone()
        };
        if expected_compressed != compressed {
            failures.push(format!(
                "{sysargs:?}: compressed python={expected_compressed} rust={compressed}",
            ));
        }
        let legacy = strings(&chain["pipeline_sysargs"]);
        let compressed_legacy =
            capture_json(sysargs::compress_pipeline_sysargs(&legacy).map(Value::from));
        if chain["compressed"] != compressed_legacy {
            failures.push(format!(
                "{sysargs:?}: compressed v4 form python={} rust={compressed_legacy}",
                chain["compressed"]
            ));
        }

        // Entry-level step splitting with a capturing executor.
        let mut steps: Vec<Value> = Vec::new();
        let result = dispatch::run_chain(&sysargs, &ctx, None, |args| {
            steps.push(args_to_fixture_json(&args));
            SuccessTuple::ok("captured")
        });
        let entry = &chain["entry"];
        let expected_steps = entry["steps"].as_array().unwrap();
        if expected_steps.len() != steps.len() {
            failures.push(format!(
                "{sysargs:?}: entry steps python={} rust={}",
                expected_steps.len(),
                steps.len()
            ));
        } else {
            for (e, a) in expected_steps.iter().zip(&steps) {
                let e = v4_chain_step_to_current(e);
                let diffs = diff_maps(&e, a);
                if !diffs.is_empty() {
                    failures.push(format!("{sysargs:?}: entry step:\n{}", diffs.join("\n")));
                }
            }
        }
        let expected = &entry["result"];
        match result {
            Ok(SuccessTuple {
                success,
                message: msg,
            }) => {
                if expected.get("success") != Some(&Value::from(success)) {
                    failures.push(format!(
                        "{sysargs:?}: entry success python={expected} rust={success}"
                    ));
                } else if !success
                    && expected
                        .get("message")
                        .and_then(Value::as_str)
                        .map(|m| m.replace("\nstart pipeline ", "\nchain "))
                        != Some(msg.clone())
                {
                    failures.push(format!(
                        "{sysargs:?}: entry message python={} rust={msg:?}",
                        expected["message"]
                    ));
                }
            }
            Err(e) => {
                if expected.get("raises") != Some(&exc_json(&e)) {
                    failures.push(format!(
                        "{sysargs:?}: entry python={expected} rust raised {}",
                        exc_json(&e)
                    ));
                }
            }
        }
    }
    report("chains", &failures, chains.len());
}

#[test]
fn parse_line_matches_python() {
    let fixture = load("args.json");
    let ctx = ctx(&fixture);
    let lines = fixture["lines"].as_array().unwrap();
    let mut failures = Vec::new();
    for case in lines {
        let line = case["line"].as_str().unwrap();
        let args = args_to_fixture_json(&parse_line(line, &ctx));
        let diffs = diff_maps(&case["args"], &args);
        if !diffs.is_empty() {
            failures.push(format!("{line:?}:\n{}", diffs.join("\n")));
        }
    }
    report("parse_line", &failures, lines.len());
}

#[test]
fn remove_leading_action_matches_python() {
    let fixture = load("args.json");
    let cases = fixture["remove_leading_action"].as_array().unwrap();
    let mut failures = Vec::new();
    for case in cases {
        let action = strings(&case["action"]);
        let rust = actions::remove_leading_action(&action, CORE_ACTIONS);
        if case["result"].get("ok") != Some(&Value::from(rust.clone())) {
            failures.push(format!(
                "{action:?}: python={} rust={rust:?}",
                case["result"]
            ));
        }
    }
    report("remove_leading_action", &failures, cases.len());
}

#[test]
fn type_functions_match_python() {
    let fixture = load("args.json");
    let ctx = ctx(&fixture);
    let funcs = &fixture["type_functions"];
    let mut failures = Vec::new();
    let mut total = 0;
    let python_exception = |e: types::ConvError, input: &str| match e {
        // Python raises the builtin's own ValueError here; argparse rewrites the message.
        types::ConvError::Invalid => {
            serde_json::json!({ "$type": "exception", "class": "ValueError", "input": input })
        }
        types::ConvError::Raise(e) => exc_json(&e),
    };
    for (name, f) in [
        (
            "parse_datetime",
            &(|s: &str| types::parse_datetime(s, &ctx))
                as &dyn Fn(&str) -> Result<PyValue, types::ConvError>,
        ),
        ("string_to_dict", &types::string_to_dict),
        ("parse_executor_keys", &types::parse_executor_keys),
        ("parse_name", &types::parse_name),
    ] {
        for case in funcs[name].as_array().unwrap() {
            total += 1;
            let input = case["input"].as_str().unwrap();
            match (f(input), case.get("ok"), case.get("raises")) {
                (Ok(v), Some(expected), _) => {
                    if v.to_fixture_json() != *expected {
                        failures.push(format!(
                            "{name}({input:?}): python={expected} rust={}",
                            v.to_fixture_json()
                        ));
                    }
                }
                (Err(e), _, Some(expected)) => {
                    let actual = python_exception(e, input);
                    let same = match actual.get("input") {
                        // Only the class is comparable for ValueError from builtins.
                        Some(_) => {
                            expected["class"] == actual["class"]
                                || expected["class"] == "JSONDecodeError"
                        }
                        None => *expected == actual,
                    };
                    if !same {
                        failures.push(format!(
                            "{name}({input:?}): python raised {expected}, rust raised {actual}"
                        ));
                    }
                }
                (Ok(v), None, Some(expected)) => failures.push(format!(
                    "{name}({input:?}): python raised {expected}, rust={}",
                    v.to_fixture_json()
                )),
                (Err(e), Some(expected), _) => failures.push(format!(
                    "{name}({input:?}): python={expected}, rust raised {}",
                    python_exception(e, input)
                )),
                _ => failures.push(format!("{name}({input:?}): malformed fixture")),
            }
        }
    }
    report("type_functions", &failures, total);
}

#[test]
fn argument_spec_matches_python_parser() {
    let fixture = load("parser.json");
    let schema = schema::arg_schema();
    let mut failures = Vec::new();
    for key in ["prog", "usage", "description", "groups"] {
        if fixture[key] != schema[key] {
            failures.push(format!(
                "{key}: python={} rust={}",
                fixture[key], schema[key]
            ));
        }
    }
    let py_args = fixture["arguments"].as_array().unwrap();
    let rs_args = schema["arguments"].as_array().unwrap();
    let py_dests: Vec<&str> = py_args
        .iter()
        .map(|a| a["dest"].as_str().unwrap())
        .collect();
    // Additive engine flags are outside the v4 schema fixture, but must remain discoverable.
    for (dest, flag) in [("run_id", "--run-id"), ("resume", "--resume")] {
        assert!(
            rs_args.iter().any(
                |arg| arg["dest"] == dest && arg["option_strings"] == serde_json::json!([flag])
            )
        );
    }
    let rs_dests: Vec<&str> = rs_args
        .iter()
        .map(|a| a["dest"].as_str().unwrap())
        .filter(|dest| !["run_id", "resume"].contains(dest))
        .filter(|dest| !spec::V5_ONLY_DESTS.contains(dest))
        .collect();
    if py_dests != rs_dests {
        failures.push(format!(
            "argument order/set differs:\n  python={py_dests:?}\n  rust={rs_dests:?}"
        ));
    }
    for py in py_args {
        let dest = py["dest"].as_str().unwrap();
        let Some(rs) = rs_args.iter().find(|a| a["dest"] == dest) else {
            failures.push(format!("{dest}: missing in Rust"));
            continue;
        };
        // The help text is written for today's behavior (rc15): only its presence is checked.
        if rs["help"].as_str().is_none_or(|h| h.trim().is_empty()) {
            failures.push(format!("{dest}.help: missing"));
        }
        for field in [
            "option_strings",
            "nargs",
            "type",
            "default",
            "const",
            "choices",
            "required",
            "metavar",
            "group",
        ] {
            if py[field] != rs[field] {
                failures.push(format!(
                    "{dest}.{field}: python={} rust={}",
                    py[field], rs[field]
                ));
            }
        }
        if py["action"] != rs["action_class"] {
            failures.push(format!(
                "{dest}.action: python={} rust={}",
                py["action"], rs["action_class"]
            ));
        }
    }
    let py_flags: usize = py_args
        .iter()
        .map(|a| a["option_strings"].as_array().unwrap().len())
        .sum();
    report("argument spec", &failures, py_flags);
}

#[test]
fn actions_registry_matches_python() {
    let fixture = load("actions.json");
    let mut failures = Vec::new();
    // serde_json maps are sorted, so compare the sets (core action names contain no `_`, so
    // registry order cannot affect `get_action`).
    let py_names: BTreeSet<&str> = fixture
        .as_object()
        .unwrap()
        .keys()
        .map(|s| s.as_str())
        .collect();
    let rs_names: BTreeSet<&str> = CORE_ACTIONS
        .iter()
        .map(|a| a.name)
        .filter(|name| !actions::V5_ONLY_ACTIONS.contains(name))
        .collect();
    if py_names != rs_names {
        failures.push(format!(
            "action order/set: python={py_names:?} rust={rs_names:?}"
        ));
    }
    for (name, info) in fixture.as_object().unwrap() {
        let Some(action) = CORE_ACTIONS.iter().find(|a| a.name == name) else {
            failures.push(format!("{name}: missing"));
            continue;
        };
        if info["function"] != action.function
            || info["accepts_executor_keys"] != action.accepts_executor_keys
        {
            failures.push(format!("{name}: function/executor_keys differ"));
        }
        let subs = info["subactions"].as_object().unwrap();
        let mut rs_subs: Vec<&str> = action
            .subactions
            .iter()
            .filter(|s| !actions::is_v5_only_subaction(action.name, s.name))
            .map(|s| s.name)
            .collect();
        let mut py_subs: Vec<&str> = subs.keys().map(|s| s.as_str()).collect();
        rs_subs.sort();
        py_subs.sort();
        if rs_subs != py_subs {
            failures.push(format!(
                "{name}: subactions python={py_subs:?} rust={rs_subs:?}"
            ));
        }
        for sub in action.subactions {
            if let Some(py) = subs.get(sub.name)
                && (py["function"] != sub.function
                    || py["accepts_executor_keys"] != sub.accepts_executor_keys)
            {
                failures.push(format!(
                    "{name}.{}: function/executor_keys differ",
                    sub.name
                ));
            }
        }
    }
    report("actions registry", &failures, CORE_ACTIONS.len());
}

/// The option strings listed in an `argparse` help page (the invocation column).
fn listed_flags(help_text: &str) -> BTreeSet<String> {
    let mut flags = BTreeSet::new();
    for line in help_text.lines() {
        let Some(rest) = line.strip_prefix("  ") else {
            continue;
        };
        if !rest.starts_with('-') {
            continue;
        }
        let invocation = rest.split("  ").next().unwrap_or_default();
        for part in invocation.split(", ") {
            let opt = part.split(' ').next().unwrap_or_default();
            if opt.starts_with('-') {
                flags.insert(opt.to_string());
            }
        }
    }
    flags
}

/// `mrsm --help` lists every v4 option (the actions come first and the help text is today's,
/// so the page is not v4's byte for byte), every option of the argument table and the flags
/// parsed ahead of it.
#[test]
fn global_help_lists_every_v4_option() {
    let python = std::fs::read_to_string(fixtures_dir().join("help").join("_global.txt")).unwrap();
    let rust = help::format_help(80);
    let py_flags = listed_flags(&python);
    let rs_flags = listed_flags(&rust);
    let missing: Vec<&String> = py_flags.difference(&rs_flags).collect();
    assert!(
        missing.is_empty(),
        "v4 options missing from --help: {missing:?}"
    );
    let mut expected: BTreeSet<String> = spec::ARGUMENTS
        .iter()
        .flat_map(|a| a.option_strings.iter().map(|s| s.to_string()))
        .collect();
    expected.extend(
        meerschaum_cli::parse::ENGINE_OPTIONS
            .iter()
            .map(|o| o.flag.to_string()),
    );
    assert_eq!(
        rs_flags, expected,
        "--help does not list every option string"
    );
    // The v4 option groups keep their titles and order, with "Access options" (rc15: the flags
    // of `edit pipes access`, `lock pipes` and `register teams`) after "Pipes" and "Pipeline
    // options" after "Sync".
    let titles = |text: &str| -> Vec<String> {
        text.lines()
            .filter(|l| l.ends_with(" options:"))
            .map(|l| l.trim_end_matches(':').to_string())
            .collect()
    };
    let mut v4_titles = titles(&python);
    let pipes = v4_titles.iter().position(|t| t == "Pipes options").unwrap();
    v4_titles.insert(pipes + 1, "Access options".into());
    let sync = v4_titles.iter().position(|t| t == "Sync options").unwrap();
    v4_titles.insert(sync + 1, "Pipeline options".into());
    assert_eq!(titles(&rust), v4_titles);
}

/// Flags mentioned in v4 per-action help (`mrsm <action> --help` prints the docstring) that are
/// not core parser flags. Each entry documents why the difference is expected.
const DOCUMENTED_NON_PARSER_FLAGS: &[(&str, &str)] = &[];

#[test]
fn per_action_help_mentions_only_known_flags() {
    let known: BTreeSet<String> = spec::ARGUMENTS
        .iter()
        .flat_map(|a| a.option_strings.iter().map(|s| s.to_string()))
        .collect();
    let flag_re = Regex::new(
        r"(?:^|[\s`'(\[])(--[A-Za-z][A-Za-z0-9-]*[A-Za-z0-9]|-[A-Za-z])(?:$|[\s`'\],.)=:])",
    )
    .unwrap();
    let mut failures = Vec::new();
    let mut checked = 0;
    let mut mentions = 0;
    for entry in std::fs::read_dir(fixtures_dir().join("help")).unwrap() {
        let path = entry.unwrap().path();
        let name = path.file_stem().unwrap().to_string_lossy().to_string();
        if name.starts_with('_') {
            continue;
        }
        checked += 1;
        let text = std::fs::read_to_string(&path).unwrap();
        for caps in flag_re.captures_iter(&text) {
            let flag = &caps[1];
            mentions += 1;
            if known.contains(flag) || DOCUMENTED_NON_PARSER_FLAGS.iter().any(|(f, _)| *f == flag) {
                continue;
            }
            failures.push(format!("{name}: mentions unknown flag {flag}"));
        }
    }
    eprintln!("per-action help: {checked} pages, {mentions} flag mentions checked");
    assert!(
        mentions > 50,
        "the flag extraction found too few mentions ({mentions})"
    );
    report("per-action help flags", &failures, checked);
}

/// A config registry over an empty root (defaults only, no writes).
fn test_config(root: &std::path::Path) -> meerschaum_core::config::Config {
    let mut opts = meerschaum_core::config::ConfigOptions::with_env(vec![
        ("MRSM_ROOT_DIR".into(), root.to_string_lossy().into_owned()),
        (
            "MRSM_PLUGINS_DIR".into(),
            root.join("plugins").to_string_lossy().into_owned(),
        ),
    ]);
    opts.allow_writes = false;
    opts.home = root.to_path_buf();
    meerschaum_core::config::Config::new(opts).unwrap()
}

fn test_settings() -> meerschaum_cli::format::FormatSettings {
    meerschaum_cli::format::FormatSettings {
        ansi: false,
        unicode: true,
        width: 80,
        cols: 80,
        no_color: false,
    }
}

/// Flags a v4 help page mentions that today's page leaves out, and why.
const REMOVED_FROM_ACTION_HELP: &[(&str, &str, &str)] = &[(
    "show.data",
    "--gui",
    "`--gui` has no effect (there is no pandasgui window)",
)];

/// `mrsm <action> [<subaction>] --help` prints help for every recorded v4 page, and that help
/// still mentions every flag the v4 page did ([`REMOVED_FROM_ACTION_HELP`] lists the
/// exceptions). The text itself is today's (rc15: no byte-for-byte v4 comparison).
#[test]
fn per_action_help_keeps_every_v4_page() {
    let fixture = load("args.json");
    let tmp = tempfile::tempdir().unwrap();
    let flag_re = Regex::new(r"(--[A-Za-z][A-Za-z0-9-]*[A-Za-z0-9])").unwrap();
    let mut failures = Vec::new();
    let mut checked = 0;
    for entry in std::fs::read_dir(fixtures_dir().join("help")).unwrap() {
        let path = entry.unwrap().path();
        let name = path.file_stem().unwrap().to_string_lossy().to_string();
        if name.starts_with('_') {
            continue;
        }
        checked += 1;
        let expected = std::fs::read_to_string(&path).unwrap();
        let mut sysargs: Vec<String> = name.split('.').map(str::to_string).collect();
        sysargs.push("--help".into());
        let mut buf: Vec<u8> = Vec::new();
        {
            let mut rt = Runtime::new(ctx(&fixture), 80, &mut buf, |_| None);
            rt.config = Some(test_config(tmp.path()));
            rt.format = Some(test_settings());
            assert_eq!(dispatch::main(&sysargs, &mut rt), 0);
        }
        let actual = String::from_utf8(buf).unwrap();
        if actual.trim().is_empty() {
            failures.push(format!("{name}: no help"));
            continue;
        }
        for caps in flag_re.captures_iter(&expected) {
            let flag = &caps[1];
            if REMOVED_FROM_ACTION_HELP
                .iter()
                .any(|(page, f, _)| *page == name && *f == flag)
            {
                continue;
            }
            if !actual.contains(flag) {
                failures.push(format!("{name}: no longer mentions {flag}:\n{actual}"));
            }
        }
        if actual.contains("v5 additions") {
            failures.push(format!("{name}: has a 'v5 additions' block"));
        }
    }
    assert_eq!(checked, 133, "expected 133 recorded help pages");
    report("per-action help pages", &failures, checked);
}

/// `mrsm <unknown> --help` prints the `show actions` table.
#[test]
fn unknown_action_help_matches_python() {
    let fixture = load("args.json");
    let tmp = tempfile::tempdir().unwrap();
    let expected =
        std::fs::read_to_string(fixtures_dir().join("help").join("_unknown_action.txt")).unwrap();
    let mut buf: Vec<u8> = Vec::new();
    {
        let mut rt = Runtime::new(ctx(&fixture), 80, &mut buf, |_| None);
        rt.config = Some(test_config(tmp.path()));
        rt.format = Some(test_settings());
        dispatch::main(&["foo".to_string(), "--help".to_string()], &mut rt);
    }
    let actual = String::from_utf8(buf).unwrap();
    // Additive v5 actions change the table's column widths and row count. Keep the v4
    // fixture immutable, and compare its vocabulary plus the explicitly approved additions.
    let words = |text: &str| {
        let mut words: Vec<String> = text.split_whitespace().map(str::to_owned).collect();
        words.sort();
        words
    };
    let mut expected_words = words(&expected);
    expected_words.extend(
        meerschaum_cli::actions::V5_ONLY_ACTIONS
            .iter()
            .map(|s| (*s).to_owned()),
    );
    expected_words.sort();
    // The columns are sized to the names: no action is abbreviated at 80 columns.
    assert!(!actual.contains('…'), "{actual}");
    let mut actual_words = words(&actual);
    actual_words.sort();
    assert_eq!(actual_words, expected_words);
    let mut listed = Vec::new();
    {
        let mut rt = Runtime::new(ctx(&fixture), 80, &mut listed, |_| None);
        rt.config = Some(test_config(tmp.path()));
        rt.format = Some(test_settings());
        dispatch::main(&["show".to_string(), "actions".to_string()], &mut rt);
    }
    assert_eq!(actual, String::from_utf8(listed).unwrap());
}

#[test]
fn dispatch_skeleton() {
    let mut buf: Vec<u8> = Vec::new();
    let fixture = load("args.json");
    let tmp = tempfile::tempdir().unwrap();
    let mut rt = Runtime::new(ctx(&fixture), 80, &mut buf, |_| None);
    rt.config = Some(test_config(tmp.path()));
    rt.format = Some(test_settings());
    let s = |v: &[&str]| v.iter().map(|x| x.to_string()).collect::<Vec<_>>();

    assert_eq!(
        dispatch::entry(&s(&["show", "version", "--nopretty"]), &mut rt),
        SuccessTuple::success()
    );
    assert_eq!(
        dispatch::entry(&s(&["show", "help"]), &mut rt),
        SuccessTuple::success()
    );
    assert_eq!(
        dispatch::entry(&s(&["show", "arguments", "-c", "sql:main"]), &mut rt),
        SuccessTuple::success()
    );
    // Verify compatibility delegation with an absent interpreter; never install packages
    // or contact an API while checking dispatch.
    // (`install plugins` and `show packages` are native now; importing a Python plugin needs the worker.)
    std::fs::create_dir_all(tmp.path().join("plugins")).unwrap();
    std::fs::write(
        tmp.path().join("plugins/synthetic_wiring_test.py"),
        "x = 1\n",
    )
    .unwrap();
    let output = std::process::Command::new(env!("CARGO_BIN_EXE_mrsm-cli"))
        .args(["verify", "plugins"])
        .env("MRSM_ROOT_DIR", tmp.path())
        .env("MRSM_PLUGINS_DIR", tmp.path().join("plugins"))
        .env("MRSM_PYTHON", tmp.path().join("absent-python"))
        .output()
        .unwrap();
    assert!(!output.status.success());
    let text = String::from_utf8_lossy(&output.stdout);
    // The worker crate refuses the interpreter with one message (W18-FX2); the result carries it.
    assert!(text.contains("could not be started"), "{text}");
    assert_eq!(
        dispatch::entry(&s(&["show", "pipe", "-i", "sql:memory"]), &mut rt),
        SuccessTuple::ok("No pipes to show.")
    );
    // Unknown actions run through `sh` (`bash -c 'foo bar'`); the test host exits 0.
    assert_eq!(
        dispatch::entry(&s(&["foo", "bar"]), &mut rt),
        SuccessTuple::success()
    );
    // `-d` becomes `start jobs`; the test host has no input, so the job is not created.
    let started = dispatch::entry(
        &s(&["install", "plugins", "synthetic_wiring_test", "-d"]),
        &mut rt,
    );
    assert!(
        !started.success && started.message.starts_with("Failed to start job"),
        "{started:?}"
    );
    assert!(
        !tmp.path().join("jobs").exists()
            || std::fs::read_dir(tmp.path().join("jobs"))
                .unwrap()
                .next()
                .is_none()
    );
    let SuccessTuple {
        success: ok,
        message: msg,
    } = dispatch::entry(
        &s(&[
            "show",
            "version",
            "+",
            "show",
            "config",
            "synthetic_missing_key",
        ]),
        &mut rt,
    );
    assert!(
        !ok && msg.contains("The action chain failed after 1 step"),
        "{msg}"
    );
    let SuccessTuple {
        success: ok,
        message: msg,
    } = dispatch::entry(&s(&["sync", "--begin", "xyz"]), &mut rt);
    assert!(!ok);
    assert_eq!(
        msg,
        "Invalid arguments:\nsync --begin xyz\n    'xyz' is not a valid datetime format."
    );

    assert_eq!(
        dispatch::main(&s(&["show", "config", "synthetic_missing_key"]), &mut rt),
        1
    );
    // PARITY (W18-SW-005): v4 exits 0 here (`--nopretty` skips the code that sets the status);
    // v5 exits 1 when the command fails (wave 18, decision 10).
    assert_eq!(
        dispatch::main(
            &s(&["show", "config", "synthetic_missing_key", "--nopretty"]),
            &mut rt
        ),
        1
    );
    assert_eq!(dispatch::main(&s(&["show", "version"]), &mut rt), 0);
    assert_eq!(dispatch::main(&s(&["--help"]), &mut rt), 0);
    assert_eq!(dispatch::main(&s(&["sync", "--help"]), &mut rt), 0);
    assert_eq!(dispatch::main(&s(&["-V"]), &mut rt), 0);
    assert_eq!(dispatch::main(&s(&["--print-arg-schema"]), &mut rt), 0);
    drop(rt);
    let out = String::from_utf8(buf).unwrap();
    assert!(out.contains(env!("CARGO_PKG_VERSION")));
    assert!(out.contains("'connector_keys': ['sql:main']"));
    assert!(out.contains("usage: mrsm [actions] {options}"));
    assert!(out.contains("\"schema_version\": 1"));
}
